const r = await fetch("https://moviebarcode.tumblr.com/tagged/leaves-of-grass", {redirect: "follow"});
const t = await r.text();
return r.status + " len=" + t.length + "\n" + t.slice(0, 3000);

const urls = [
 "https://moviebarcode.tumblr.com/tagged/leaves-of-grass-2009",
 "https://moviebarcodes.tumblr.com",
 "https://moviebarcode.tumblr.com/search/candy",
 "https://moviebarcode.tumblr.com/search/leaves+of+grass",
 "https://moviebarcode.tumblr.com/search/sliding+doors",
];
const out = [];
for (const u of urls) {
  try {
    const r = await fetch(u, {redirect: "follow"});
    const t = await r.text();
    const titles = [...t.matchAll(/<title>([^<]*)<\/title>/g)].map(m=>m[1]);
    const posts = (t.match(/media\.tumblr\.com[^"')]+/g) || []).slice(0,5);
    out.push(`${u} -> ${r.status} title=${titles[0]||"?"} media=${posts.length}\n  ${posts.join("\n  ")}`);
  } catch(e) { out.push(u + " -> ERR " + e.message); }
}
return out.join("\n\n");

