async function get(u){const r=await fetch(u,{headers:{"user-agent":"Mozilla/5.0"}});return r;}
const pages = ["candy","leaves of grass","sliding doors","the rebound","the little hours","georgia rule","man of the year","importance of being earnest","take me home tonight","fifty shades of black"];
const found = {};
for (const q of pages) {
  const u = "https://moviebarcode.tumblr.com/search/" + encodeURIComponent(q);
  const r = await get(u);
  const t = await r.text();
  const imgs = [...t.matchAll(/https?:\\?\/\\?\/\d+\.media\.tumblr\.com\\?\/[a-z0-9]+\\?\/tumblr_[a-z0-9]+_[a-z0-9_]+\.jpg/g)]
    .map(m=>m[0].replace(/\\\//g,"/"));
  const uniq = [...new Set(imgs)];
  found[q] = uniq;
}
return Object.entries(found).map(([k,v])=>`${k}: ${v.length}\n  ${v.slice(0,8).join("\n  ")}`).join("\n\n");

